      SUBROUTINE PHASECC     CONSTRAINS THE PHASE ADVANCE OF THE BEAMC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      LOGICAL         LOGICC-----------------------------------------------------------------------CC     DETERMINE PHASE SHIFT IN BOTH TRANSVERSE PLANESC      IF (.NOT. RECENT) CALL BEAM      J = KCON      K = J + 1C      IF (J .EQ. 1) THEN        COC = PSIX/UNITO(12)        SNP = SNPX        CSP = CSPX      ENDIFC      IF (J .EQ. 3) THEN        COC = PSIY/UNITO(12)        SNP = SNPY        CSP = CSPY      ENDIFCC     ADJUST UPWARD OR DOWNWARD BY 2*PIC      PID = PI/UNITO(12)   10 IF (COC .GT. DE0 - PID) GO TO 20      COC = COC + 2.0*PID      GO TO 10C   20 IF (COC .LT. DE0 + PID) GO TO 30      COC = COC - 2.0*PID      GO TO 20CC     DIFFERENCE BETWEEN ACTUAL AND DESIRED VALUESC   30 A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 150CC     DERIVATIVE WRT VARIED PARAMETERC      IF (NV3 .LT. 1) GO TO 100      CW = 1.0/SD**2C      DO 90 N = 1, NV1      IF (R2P) GO TO 40      IF (.NOT. SVP(N)) GO TO 90      SVJJ = SV(J,J,N)      SVJK = SV(J,K,N)      GO TO 80C   40 SVJJ = 0.0      SVJK = 0.0      IF (SVP(N)) THEN        DO 45 L1 = 1, 6        DO 45 L2 = 1, 6        SVJJ = SVJJ + RC2(J,L1)*SV(L1,L2,N)*RC2(J,L2)        SVJK = SVJK + RC2(J,L1)*SV(L1,L2,N)*RC2(K,L2)   45   CONTINUE      ENDIFC   50 IF (R2VP(N)) THEN        DO 75 L1 = 1, 6        DO 75 L2 = 1, 6        SVJJ = SVJJ + R2V(J,L1,N)*SI(L1,L2)*RC2(J,L2)     1       + RC2(J,L1)*SI(L1,L2)*R2V(J,L2,N)        SVJK = SVJK + R2V(J,L1,N)*SI(L1,L2)*RC2(K,L2)     1       + RC2(J,L1)*SI(L1,L2)*R2V(K,L2,N)   75   CONTINUE      ENDIFC   80 EPS0 = SQRT(SI(J,J)*SI(K,K) - SI(K,J)**2)      EPS1 = SIT(J,J)*SIT(K,K) - SIT(K,J)**2      IF (EPS1 .GE. 0.0) THEN        EPS1 = SQRT(EPS1)      ELSE        EPS1 = 0.0      ENDIF      IF (EPS0 .EQ. 0.0 .OR. EPS1 .EQ. 0.0) THEN        DOPH = .FALSE.        GO TO 90      ENDIF      BETA0 = SI(J,J)/EPS0      BETA1 = SIT(J,J)/EPS1      ALPHA0 = - SI(K,J)/EPS0      SNP = RC2(J,K)/SQRT(BETA0*BETA1)      CSP = RC2(J,J)*SQRT(BETA0/BETA1) - ALPHA0*SNPC      ZAP = BETA0*BETA1      ZIP = SQRT(ZAP)      SNAP = SQRT(BETA0/BETA1)      IF (SVP(N)) THEN        DBETA0 = SV(J,J,N)/EPS0        DALPH0 = - SV(J,K,N)/EPS0      ELSE        DBETA0 = 0.0        DALPH0 = 0.0      ENDIF      DBETA1 = SVJJ/EPS1      DSNP = (ZIP*R2V(J,K,N)     1     - 0.5*RC2(J,K)*(DBETA1*BETA0 + BETA1*DBETA0)/ZIP)/ZAP      DCSP = R2V(J,J,N)*SNAP     1     + 0.5*RC2(J,J)*(BETA1*DBETA0     2     - DBETA1*BETA0)/(SNAP*BETA1**2)     3     - DALPH0*SNP - ALPHA0*DSNP      DTPSI = (CSP*DSNP - DCSP*SNP)/CSP**2      DPSI = CSP**2*DTPSI      A(N+1) = DPSI/UNITO(12)   90 CONTINUE  100 CALL GATHERC  150 RETURN      END